// Generated by AI.
using UnityEngine;

namespace GrindHero.Presentation
{
    public sealed class StylizedActorView : MonoBehaviour
    {
        public Transform body;
        public Transform leftLeg;
        public Transform rightLeg;
        public Transform weaponArm;
        public Transform weapon;
        public Transform telegraph;
        public Transform targetRing;
        public Renderer coat;
        public float attackRadius = 2f;

        private MaterialPropertyBlock _properties;
        private static readonly int BaseColor = Shader.PropertyToID("_BaseColor");
        private Vector3 _previousPosition;
        private Vector3 _bodyRest;
        private float _step;
        private float _windupDuration;
        private float _windupRemaining;
        private float _swingRemaining;
        private float _flashRemaining;
        private Color _coatColor;

        private void Awake()
        {
            _properties = new MaterialPropertyBlock();
            _previousPosition = transform.position;
            _bodyRest = body.localPosition;
            _coatColor = coat.sharedMaterial.color;
            telegraph.gameObject.SetActive(false);
            targetRing.gameObject.SetActive(false);
        }

        public void Windup(float duration)
        {
            _windupDuration = Mathf.Max(0.01f, duration);
            _windupRemaining = _windupDuration;
        }

        public void Strike()
        {
            _windupRemaining = 0f;
            _swingRemaining = 0.18f;
            telegraph.gameObject.SetActive(false);
        }

        public void CancelAttack()
        {
            _windupRemaining = 0f;
            telegraph.gameObject.SetActive(false);
        }

        public void SetTargeted(bool targeted)
        {
            targetRing.gameObject.SetActive(targeted);
        }

        public void Flash()
        {
            _flashRemaining = 0.12f;
        }

        private void LateUpdate()
        {
            var delta = Time.deltaTime;
            var displacement = transform.position - _previousPosition;
            _previousPosition = transform.position;
            var moving = displacement.sqrMagnitude > 0.000001f && delta > 0f;
            if (moving)
            {
                _step += delta * 11f;
            }

            var stride = moving ? Mathf.Sin(_step) * 27f : 0f;
            leftLeg.localRotation = Quaternion.Euler(stride, 0f, 0f);
            rightLeg.localRotation = Quaternion.Euler(-stride, 0f, 0f);
            body.localPosition = _bodyRest + Vector3.up * (moving ? Mathf.Abs(Mathf.Sin(_step)) * 0.06f : 0f);
            _windupRemaining = Mathf.Max(0f, _windupRemaining - delta);
            _swingRemaining = Mathf.Max(0f, _swingRemaining - delta);
            _flashRemaining = Mathf.Max(0f, _flashRemaining - delta);
            var charging = _windupRemaining > 0f;
            telegraph.gameObject.SetActive(charging);
            var charge = charging ? 1f - _windupRemaining / _windupDuration : 0f;
            telegraph.localScale = Vector3.one * (attackRadius / transform.lossyScale.x) *
                (0.65f + charge * 0.35f);
            weaponArm.localRotation = _swingRemaining > 0f
                ? Quaternion.Euler(0f, Mathf.Lerp(90f, -70f, _swingRemaining / 0.18f), -35f)
                : Quaternion.Euler(charging ? -85f * charge : stride * 0.2f, 0f, charging ? -25f : -8f);
            _properties.SetColor(BaseColor, _flashRemaining > 0f ? Color.white : _coatColor);
            coat.SetPropertyBlock(_properties);
        }
    }
}
